  "labhealth.c.backupUnlinked.what": "{name} ಅನ್ನು ಬ್ಯಾಕಪ್ ಗಮ್ಯಸ್ಥಾನವಾಗಿ ಮಾಡೆಲ್ ಮಾಡಲಾಗಿದೆ, ಆದರೆ ಟೋಪೋಲಜಿ ಅದಕ್ಕೆ ಯಾವುದೇ ಸಂಪರ್ಕವನ್ನು ತೋರಿಸುವುದಿಲ್ಲ.",
  "labhealth.c.backupUnlinked.why": "ಮಾಡೆಲ್ ಮಾಡಿರುವ ಮಾರ್ಗವಿಲ್ಲದೆ, ಯಾವ ಡೇಟಾ ಈ ಬ್ಯಾಕಪ್‌ಗೆ ತಲುಪುತ್ತದೆ ಎಂಬುದು ಅಸ್ಪಷ್ಟವಾಗಿದೆ.",
  "labhealth.c.backupUnlinked.action": "ಅದು ಬ್ಯಾಕಪ್ ಮಾಡುವ ಸಾಧನಕ್ಕೆ ಟೋಪೋಲಜಿಯಲ್ಲಿ ಸಂಪರ್ಕಿಸಿ.",
  "labhealth.c.backupModel.title": "ಬ್ಯಾಕಪ್ ಅನ್ನು ಮಾಡೆಲ್ ಮಾಡಲಾಗಿದೆ, ಪರಿಶೀಲಿಸಿಲ್ಲ",
  "labhealth.c.backupModel.what": "ನಿಮ್ಮ ಮಾಡೆಲ್‌ನಲ್ಲಿ ಬ್ಯಾಕಪ್ ಗಮ್ಯಸ್ಥಾನ ಅಸ್ತಿತ್ವದಲ್ಲಿದೆ. ಬ್ಯಾಕಪ್‌ಗಳು ನಿಜವಾಗಿ ಚಾಲನೆಯಲ್ಲಿವೆ ಎಂದು ಅಪ್ಲಿಕೇಶನ್ ದೃಢೀಕರಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ — ನಿಮ್ಮ ಬ್ಯಾಕಪ್ ಸಾಫ್ಟ್‌ವೇರ್ ಪರಿಶೀಲಿಸಿ.",
  "labhealth.c.isolated.title": "{name} ಗೆ ಯಾವುದೇ ಸಂಪರ್ಕಗಳಿಲ್ಲ",
  "labhealth.c.isolated.what": "ಪ್ರಸ್ತುತ ಟೋಪೋಲಜಿ {name} ಗೆ ಇತರ ಸಾಧನಗಳಿಗೆ ಯಾವುದೇ ಸಂಪರ್ಕಗಳಿಲ್ಲ ಎಂದು ತೋರಿಸುತ್ತದೆ.",
