  "error.notFoundBody": "ನೀವು ಹುಡುಕುತ್ತಿರುವ ಪುಟವು ಅಸ್ತಿತ್ವದಲ್ಲಿಲ್ಲ ಅಥವಾ ಸರಿಸಲಾಗಿದೆ.",
  "error.pageLoadTitle": "ಈ ಪುಟ ಲೋಡ್ ಆಗಲಿಲ್ಲ",
  "error.pageLoadBody": "ನಮ್ಮ ಕಡೆಯಿಂದ ಏನೋ ತಪ್ಪಾಗಿದೆ. ನೀವು ರಿಫ್ರೆಶ್ ಮಾಡಲು ಪ್ರಯತ್ನಿಸಬಹುದು ಅಥವಾ ಮನೆಗೆ ಹಿಂತಿರುಗಿ.",
  "guide.title": "ತ್ವರಿತ ಮಾರ್ಗದರ್ಶಿ",
  "guide.stepCount": "{current} ರಲ್ಲಿ {total} ಹಂತ",
  "guide.close": "ಮಾರ್ಗದರ್ಶಿ ಮುಚ್ಚಿ",
  "guide.skip": "ಮಾರ್ಗದರ್ಶಿಯನ್ನು ಬಿಟ್ಟುಬಿಡಿ",
  "guide.start": "ನಿರ್ಮಿಸಲು ಪ್ರಾರಂಭಿಸಿ",
  "guide.1.title": "1. ಯೋಜನೆಯನ್ನು ರಚಿಸಿ",
  "guide.1.body": "ಯೋಜನೆಯು ಒಂದು ಹೋಮ್‌ಲ್ಯಾಬ್ ವಿನ್ಯಾಸವಾಗಿದೆ. ಇದಕ್ಕೆ ಹೆಸರು, ಗುರಿ ಮತ್ತು ಐಚ್ಛಿಕ ಬಜೆಟ್ ನೀಡಿ - ನೀವು ನಿರ್ಮಿಸುವ ಎಲ್ಲವನ್ನೂ ಆ ಯೋಜನೆಗೆ ಉಳಿಸಲಾಗುತ್ತದೆ.",
  "guide.2.title": "2. ಹಾರ್ಡ್ವೇರ್ ಪ್ರದೇಶವನ್ನು ತೆರೆಯಿರಿ",
  "guide.2.body": "ಹಾರ್ಡ್‌ವೇರ್ ಪಟ್ಟಿಯು ನೀವು ಬಳಸಬಹುದಾದ ಸಾಧನಗಳನ್ನು ಹೊಂದಿದೆ. ಪ್ರತಿ ನಮೂದು ನಿಮ್ಮ ಹೋಮ್‌ಲ್ಯಾಬ್‌ನಲ್ಲಿನ ನಿಜವಾದ ತುಣುಕಿನ ಗೇರ್ ಅನ್ನು ಪ್ರತಿನಿಧಿಸುತ್ತದೆ.",
  "guide.3.title": "3. ಒಂದು ಘಟಕವನ್ನು ಸೇರಿಸಿ",
  "guide.3.body": "ಬ್ಲೂಪ್ರಿಂಟ್‌ನಲ್ಲಿ ಇರಿಸಲು ಐಟಂ ಅನ್ನು ಆರಿಸಿ. ಇದು ಅದರ ಬೆಲೆ ಮತ್ತು ಪ್ರಮುಖ ವಿಶೇಷಣಗಳನ್ನು ತೋರಿಸುವ ಕಾರ್ಡ್‌ನಂತೆ ಗೋಚರಿಸುತ್ತದೆ.",
  "guide.4.title": "4. ಅದನ್ನು ಸರಿಸಿ",
  "guide.4.body": "ಅದನ್ನು ಮರುಸ್ಥಾಪಿಸಲು ಕಾರ್ಡ್ ಅನ್ನು ಒತ್ತಿ ಮತ್ತು ಎಳೆಯಿರಿ. ಒಂದು ಸಣ್ಣ ಟ್ಯಾಪ್ ಬದಲಿಗೆ ಅದರ ವಿವರಗಳನ್ನು ತೆರೆಯುತ್ತದೆ ಮತ್ತು ಖಾಲಿ ಜಾಗವನ್ನು ಎಳೆಯುವುದರಿಂದ ಇಡೀ ನೀಲನಕ್ಷೆಯನ್ನು ಚಲಿಸುತ್ತದೆ.",
  "guide.5.title": "5. ಸಂಪರ್ಕ ನೋಡ್ ಅನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿ",
  "guide.5.body": "ಪ್ರತಿಯೊಂದು ಕಾರ್ಡ್ ಮೇಲಿನ ಮತ್ತು ಕೆಳಭಾಗದಲ್ಲಿ ಸಣ್ಣ ಸುತ್ತಿನ ನೋಡ್ ಅನ್ನು ಹೊಂದಿರುತ್ತದೆ. ಒಂದನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿ - ಅದು ಎರಡನೇ ನೋಡ್‌ಗಾಗಿ ಕಾಯುತ್ತಿದೆ ಎಂದು ತೋರಿಸಲು ಅದು ಬೆಳಗುತ್ತದೆ.",
  "guide.6.title": "6. ಮತ್ತೊಂದು ಘಟಕದ ನೋಡ್ ಅನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿ",
  "guide.6.body": "ನೀವು ಲಿಂಕ್ ಮಾಡಲು ಬಯಸುವ ಘಟಕದ ಮೇಲೆ ನೋಡ್ ಅನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿ. ಮೊದಲ ನೋಡ್ ಅನ್ನು ಮತ್ತೆ ಟ್ಯಾಪ್ ಮಾಡುವುದರಿಂದ ರದ್ದುಗೊಳ್ಳುತ್ತದೆ.",
  "guide.7.title": "7. ಹಸಿರು ರೇಖೆಯನ್ನು ನೋಡಿ",
  "guide.7.body": "ಹಸಿರು ರೇಖೆಯು ಈಗ ಎರಡು ಘಟಕಗಳನ್ನು ಸೇರುತ್ತದೆ ಮತ್ತು ನೀವು ವಸ್ತುಗಳನ್ನು ಚಲಿಸುವಾಗ ಅವುಗಳನ್ನು ಅನುಸರಿಸುತ್ತದೆ. ಅದರ ಪ್ರಕಾರವನ್ನು ನೋಡಲು ಅಥವಾ ಅದನ್ನು ತೆಗೆದುಹಾಕಲು ರೇಖೆಯನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿ.",
  "guide.8.title": "8. ಓಪನ್ ಅನಾಲಿಸಿಸ್",
  "guide.8.body": "ವೆಚ್ಚ, ವಿದ್ಯುತ್ ಡ್ರಾ, ಶಕ್ತಿಯ ಬಳಕೆ, ಸಂಗ್ರಹಣೆ ಮತ್ತು ನೆಟ್‌ವರ್ಕ್ ಸಾಮರ್ಥ್ಯವನ್ನು ಕೆಲಸ ಮಾಡಲು ವಿಶ್ಲೇಷಣೆಯು ನಿಮ್ಮ ಹಾರ್ಡ್‌ವೇರ್ ಮತ್ತು ಸ್ಪೆಕ್ಸ್ ಅನ್ನು ಬಳಸುತ್ತದೆ.",
  "guide.9.title": "9. ವರದಿಯನ್ನು ವೀಕ್ಷಿಸಿ",
  "guide.9.body": "ವರದಿಯು ನೀವು ವಿನ್ಯಾಸಗೊಳಿಸಿದ ಹೋಮ್‌ಲ್ಯಾಬ್ ಅನ್ನು ಸಾರಾಂಶಗೊಳಿಸುತ್ತದೆ: ಭಾಗಗಳ ಪಟ್ಟಿ, ಮೊತ್ತಗಳು ಮತ್ತು ವಿಶ್ಲೇಷಣೆ, ಹಂಚಿಕೊಳ್ಳಲು ಅಥವಾ ಇರಿಸಿಕೊಳ್ಳಲು ಸಿದ್ಧವಾಗಿದೆ.",
  "feedback.back": "ಸೆಟ್ಟಿಂಗ್‌ಗಳಿಗೆ ಹಿಂತಿರುಗಿ",
  "feedback.eyebrow": "ಪ್ರತಿಕ್ರಿಯೆ",
  "feedback.title": "ದೋಷವನ್ನು ವರದಿ ಮಾಡಿ ಅಥವಾ ಸುಧಾರಣೆಯನ್ನು ಸೂಚಿಸಿ",
  "feedback.description": "ಏನಾಯಿತು ಅಥವಾ ನೀವು ಮುಂದೆ ಏನನ್ನು ನೋಡಲು ಬಯಸುತ್ತೀರಿ ಎಂದು ನಮಗೆ ತಿಳಿಸಿ.",
