  "public.backAbout": "ಬಗ್ಗೆ ಗೆ ಹಿಂತಿರುಗಿ",
  "public.lastUpdated": "ಕೊನೆಯದಾಗಿ ನವೀಕರಿಸಲಾಗಿದೆ {date} · {app}",
  "about.title": "ಹೋಮ್‌ಲ್ಯಾಬ್ ಯೋಜನೆಯನ್ನು ಸುಲಭಗೊಳಿಸಲು ಹೋಮ್‌ಲ್ಯಾಬ್ ಆರ್ಕಿಟೆಕ್ಟ್ ಅಸ್ತಿತ್ವದಲ್ಲಿದೆ.",
  "about.intro1": "ಮೊದಲು ಹಾರ್ಡ್‌ವೇರ್ ಖರೀದಿಸಿ ಮತ್ತು ನಂತರ ಎಲ್ಲವನ್ನೂ ಕಂಡುಹಿಡಿಯುವ ಬದಲು, ಹೋಮ್‌ಲ್ಯಾಬ್ ಆರ್ಕಿಟೆಕ್ಟ್ ನಿಮಗೆ ಮೊದಲು ಸಿಸ್ಟಮ್ ಅನ್ನು ವಿನ್ಯಾಸಗೊಳಿಸಲು ಅನುಮತಿಸುತ್ತದೆ. ನೀವು ಘಟಕಗಳನ್ನು ಸೇರಿಸಿ, ಅವುಗಳನ್ನು ಸಂಪರ್ಕಿಸಿ ಮತ್ತು ನಿಮ್ಮ ಹೋಮ್‌ಲ್ಯಾಬ್‌ಗೆ ಎಷ್ಟು ವೆಚ್ಚವಾಗುತ್ತದೆ, ಅದು ಎಷ್ಟು ಶಕ್ತಿಯನ್ನು ಸೆಳೆಯುತ್ತದೆ, ನೀವು ಎಷ್ಟು ಸಂಗ್ರಹಣೆಯನ್ನು ಹೊಂದಿರುತ್ತೀರಿ ಮತ್ತು ನಿಮ್ಮ ನೆಟ್‌ವರ್ಕ್ ಹೇಗಿರುತ್ತದೆ - ಎಲ್ಲವನ್ನೂ ನೀವು ಒಂದೇ ಖರೀದಿಯನ್ನು ಮಾಡುವ ಮೊದಲು ತಕ್ಷಣವೇ ನೋಡಿ.",
  "about.intro2": "ಗುರಿ ಸರಳವಾಗಿದೆ: ಬಿಲ್ಡರ್‌ಗಳು ಉತ್ತಮ ನಿರ್ಧಾರಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳಲು, ದುಬಾರಿ ತಪ್ಪುಗಳನ್ನು ತಪ್ಪಿಸಲು ಮತ್ತು ಅವರು ನಿಜವಾಗಿ ಅರ್ಥಮಾಡಿಕೊಳ್ಳುವ ಹೋಮ್‌ಲ್ಯಾಬ್‌ನೊಂದಿಗೆ ಕೊನೆಗೊಳ್ಳಲು ಸಹಾಯ ಮಾಡಿ.",
  "about.information": "ಮಾಹಿತಿ",
  "about.design": "ಮೊದಲು ವಿನ್ಯಾಸ",
  "about.designDesc": "ಹಾರ್ಡ್‌ವೇರ್‌ನಲ್ಲಿ ಡಾಲರ್ ಖರ್ಚು ಮಾಡುವ ಮೊದಲು ಪೂರ್ಣ ವ್ಯವಸ್ಥೆಯನ್ನು ಯೋಜಿಸಿ.",
  "about.enthusiasts": "ಉತ್ಸಾಹಿಗಳಿಂದ ನಿರ್ಮಿಸಲಾಗಿದೆ",
  "about.enthusiastsDesc": "ಹೋಮ್‌ಲ್ಯಾಬರ್‌ಗಳಿಂದ ಮಾಡಲ್ಪಟ್ಟಿದೆ, ಹೋಮ್‌ಲ್ಯಾಬರ್‌ಗಳಿಗಾಗಿ — ಎಂಟರ್‌ಪ್ರೈಸ್ ಟೂಲಿಂಗ್‌ನಿಂದ ಅಳವಡಿಸಲಾಗಿಲ್ಲ.",
  "about.analysis": "ಮುಖ್ಯವಾದ ವಿಶ್ಲೇಷಣೆ",
  "about.analysisDesc": "ವೆಚ್ಚ, ಶಕ್ತಿ, ಸಂಗ್ರಹಣೆ ಮತ್ತು ನೆಟ್‌ವರ್ಕ್ ಒಳನೋಟಗಳು ವಾಸ್ತವವಾಗಿ ನಿರ್ಧಾರಗಳನ್ನು ತಿಳಿಸುತ್ತವೆ.",
  "about.output": "ವೃತ್ತಿಪರ ಔಟ್ಪುಟ್",
  "about.outputDesc": "ನಿಮ್ಮ ವಿನ್ಯಾಸವನ್ನು ನಿರ್ಮಿಸುವಾಗ ನೀವು ಅನುಸರಿಸಬಹುದಾದ ನೀಲನಕ್ಷೆಯಾಗಿ ಪರಿವರ್ತಿಸಿ.",
  "about.privacy": "ಗೌಪ್ಯತೆ",
  "about.privacyDesc": "ಹೋಮ್‌ಲ್ಯಾಬ್ ಆರ್ಕಿಟೆಕ್ಟ್ ನಿಮ್ಮ ಪ್ರಾಜೆಕ್ಟ್‌ಗಳನ್ನು ನಿಮ್ಮ ಸಾಧನದಲ್ಲಿ ಸ್ಥಳೀಯವಾಗಿ ಸಂಗ್ರಹಿಸುತ್ತದೆ. ಯಾವುದೇ ಖಾತೆಯ ಅಗತ್ಯವಿಲ್ಲ ಮತ್ತು ನಿಮ್ಮ ಪ್ರಾಜೆಕ್ಟ್ ಡೇಟಾವನ್ನು ಯಾವುದೇ ಸರ್ವರ್‌ಗೆ ಕಳುಹಿಸಲಾಗುವುದಿಲ್ಲ.",
  "about.readPrivacy": "ಗೌಪ್ಯತೆ ನೀತಿಯನ್ನು ಓದಿ",
  "about.termsTitle": "ನಿಯಮಗಳು ಮತ್ತು ಹಕ್ಕು ನಿರಾಕರಣೆ",
  "about.termsDesc": "ಎಲ್ಲಾ ಲೆಕ್ಕಾಚಾರಗಳು - ವೆಚ್ಚ, ಶಕ್ತಿ, ಸಂಗ್ರಹಣೆ ಮತ್ತು ನೆಟ್‌ವರ್ಕ್ - ವಿಶಿಷ್ಟವಾದ ಹಾರ್ಡ್‌ವೇರ್ ವಿಶೇಷಣಗಳನ್ನು ಆಧರಿಸಿದ ಅಂದಾಜುಗಳಾಗಿವೆ. ನಿಜವಾದ ಫಲಿತಾಂಶಗಳು ಬದಲಾಗುತ್ತವೆ. ಖರೀದಿಸುವ ಮೊದಲು ತಯಾರಕರೊಂದಿಗೆ ಯಾವಾಗಲೂ ವಿಶೇಷಣಗಳನ್ನು ಪರಿಶೀಲಿಸಿ.",
  "about.support": "ಬೆಂಬಲ ಮತ್ತು ಪ್ರತಿಕ್ರಿಯೆ",
  "about.supportDesc": "ದೋಷ ಕಂಡುಬಂದಿದೆಯೇ ಅಥವಾ ವೈಶಿಷ್ಟ್ಯವನ್ನು ಸೇರಿಸಬೇಕೆ? ಅಪ್ಲಿಕೇಶನ್‌ನಲ್ಲಿ ಪ್ರತಿಕ್ರಿಯೆ ಫಾರ್ಮ್ ಮೂಲಕ ಅದನ್ನು ಕಳುಹಿಸಿ.",
  "about.openFeedback": "ಪ್ರತಿಕ್ರಿಯೆ ಫಾರ್ಮ್ ತೆರೆಯಿರಿ",
  "explore.title": "ಉದಾಹರಣೆ ಹೋಮ್‌ಲ್ಯಾಬ್ ಆರ್ಕಿಟೆಕ್ಚರ್‌ಗಳು",
  "explore.description": "ಸ್ಫೂರ್ತಿಗಾಗಿ ಕ್ಯುರೇಟೆಡ್ ಸೆಟಪ್‌ಗಳನ್ನು ಬ್ರೌಸ್ ಮಾಡಿ. ಇವುಗಳು ಉಲ್ಲೇಖ ವಿನ್ಯಾಸಗಳಾಗಿವೆ - ಅವುಗಳನ್ನು ನಿಮ್ಮ ಸ್ವಂತ ಯೋಜನೆಗೆ ಆರಂಭಿಕ ಹಂತವಾಗಿ ಬಳಸಿ.",
