  "phrase.5f81ac85e239": "ಸಂಪೂರ್ಣ ಒಳಹರಿವು-0",
  "phrase.13662f2b2d71": "ಸಂಪೂರ್ಣ ಇನ್ಸೆಟ್-0 ಗ್ರಿಡ್-ಬಿಜಿ ಅಪಾರದರ್ಶಕತೆ-60",
  "phrase.f840e565f128": "ಸಂಪೂರ್ಣ ಒಳಹರಿವು-0 w-ಪೂರ್ಣ h-ಪೂರ್ಣ",
  "phrase.4054d386947c": "ಸಂಪೂರ್ಣ ಒಳಸೇರಿಸುವಿಕೆ-0 z-0 w-ಪೂರ್ಣ h-ಪೂರ್ಣ ಪಾಯಿಂಟರ್-ಈವೆಂಟ್‌ಗಳು-ಯಾವುದೂ ಇಲ್ಲ",
  "phrase.ef796a9e29d0": "ಸಂಪೂರ್ಣ ಎಡ-0 ಟಾಪ್-0 ಕೆಳಗೆ-0 ಅನಿಮೇಟ್-ಸ್ಲೈಡ್-ಇನ್-ಬಲ",
