  "phrase.ef341d0fd3b8": "ವಿಶ್ಲೇಷಣೆ.ನೋ ಪ್ರಮುಖ ಸಮಸ್ಯೆಗಳು",
  "phrase.fd9766f482cf": "ವಿಶ್ಲೇಷಣೆ",
