  "phrase.6c5801dbac82": "ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ: ಅಪಾರದರ್ಶಕತೆ-40 ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ:ಕರ್ಸರ್-ಅನುಮತಿಸಲಾಗಿಲ್ಲ",
  "phrase.9304324157fb": "ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ: ಅಪಾರದರ್ಶಕತೆ-50 ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ: ಕರ್ಸರ್-ಅನುಮತಿಸಲಾಗಿಲ್ಲ",
