  "report.electricityDisclaimer": "ವಿದ್ಯುತ್ ಅಂದಾಜುಗಳು ಪ್ರತಿ ಘಟಕಕ್ಕೆ ಕಾನ್ಫಿಗರ್ ಮಾಡಲಾದ ವಿದ್ಯುತ್ ಊಹೆಗಳು ಮತ್ತು ಈ ಯೋಜನೆಗೆ ಕಾನ್ಫಿಗರ್ ಮಾಡಲಾದ ವಿದ್ಯುತ್ ದರವನ್ನು ಆಧರಿಸಿವೆ. ನಿಜವಾದ ಬಳಕೆ ಬದಲಾಗಬಹುದು.",
  "report.rawStorageDisclaimer": "ಕಚ್ಚಾ ಸಂಗ್ರಹಣೆಯು RAID, ಫೈಲ್‌ಸಿಸ್ಟಮ್ ಓವರ್‌ಹೆಡ್ ಅಥವಾ ಸಮಾನತೆಯ ಮೊದಲು ಒಟ್ಟು ಡಿಸ್ಕ್ ಸಾಮರ್ಥ್ಯವಾಗಿದೆ. ಬಳಸಬಹುದಾದ ಸಂಗ್ರಹಣೆ ಕಡಿಮೆ ಇರುತ್ತದೆ. ಈ ಆವೃತ್ತಿಯಲ್ಲಿ ಬಳಸಬಹುದಾದ ಸಂಗ್ರಹಣೆಯನ್ನು ಲೆಕ್ಕಹಾಕಲಾಗಿಲ್ಲ.",
  "report.missingDataDisclaimer": "ಕಾಣೆಯಾದ ಡೇಟಾವು ಆರ್ಕಿಟೆಕ್ಚರ್ ಸಮಸ್ಯೆಯನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಸೂಚಿಸುವುದಿಲ್ಲ. ವಿನ್ಯಾಸದ ಈ ಅಂಶವನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ಮೌಲ್ಯಮಾಪನ ಮಾಡಲು ಸಾಕಷ್ಟು ಮಾಹಿತಿ ಇಲ್ಲ ಎಂದರ್ಥ.",
