  "legal.privacySummary": "ಹೋಮ್‌ಲ್ಯಾಬ್ ಆರ್ಕಿಟೆಕ್ಟ್ ನಿಮ್ಮ ಮಾಹಿತಿಯನ್ನು ಹೇಗೆ ನಿರ್ವಹಿಸುತ್ತಾರೆ.",
  "legal.privacyIntro": "ಹೋಮ್‌ಲ್ಯಾಬ್ ಆರ್ಕಿಟೆಕ್ಟ್ ಆಫ್‌ಲೈನ್-ಮೊದಲ ಯೋಜನಾ ಸಾಧನವಾಗಿದೆ. ಇದಕ್ಕೆ ಖಾತೆಯ ಅಗತ್ಯವಿರುವುದಿಲ್ಲ ಮತ್ತು ಅದು ನಿಮ್ಮ ಯೋಜನೆಗಳನ್ನು ನಮಗೆ ಅಥವಾ ಬೇರೆಯವರಿಗೆ ಕಳುಹಿಸುವುದಿಲ್ಲ. ನೀವು ರಚಿಸುವ ಎಲ್ಲವೂ ನೀವು ಅದನ್ನು ರಚಿಸಲು ಬಳಸಿದ ಸಾಧನ ಅಥವಾ ಬ್ರೌಸರ್‌ನ ಸಂಗ್ರಹಣೆಯಲ್ಲಿ ಉಳಿಯುತ್ತದೆ.",
  "legal.termsSummary": "ನೀವು HomeLab ಆರ್ಕಿಟೆಕ್ಟ್ ಅನ್ನು ಬಳಸುವಾಗ ಅನ್ವಯಿಸುವ ನಿಯಮಗಳು.",
  "legal.termsAcceptance": "ಹೋಮ್‌ಲ್ಯಾಬ್ ಆರ್ಕಿಟೆಕ್ಟ್ ಅನ್ನು ಸ್ಥಾಪಿಸುವ ಮೂಲಕ ಅಥವಾ ಬಳಸುವ ಮೂಲಕ ನೀವು ಈ ನಿಯಮಗಳನ್ನು ಒಪ್ಪುತ್ತೀರಿ. ನೀವು ಒಪ್ಪದಿದ್ದರೆ, ದಯವಿಟ್ಟು ಅಪ್ಲಿಕೇಶನ್ ಬಳಸುವುದನ್ನು ನಿಲ್ಲಿಸಿ.",
  "legal.termsPurpose": "ಹೋಮ್ ಲ್ಯಾಬ್ ಆರ್ಕಿಟೆಕ್ಟ್ ನಿಮಗೆ ಹೋಮ್ ಲ್ಯಾಬ್ ಲೇಔಟ್ ಅನ್ನು ವಿನ್ಯಾಸಗೊಳಿಸಲು, ಹಾರ್ಡ್‌ವೇರ್ ಘಟಕಗಳನ್ನು ಸೇರಿಸಲು, ಅವುಗಳನ್ನು ಸಂಪರ್ಕಿಸಲು ಮತ್ತು ಆ ವಿನ್ಯಾಸಕ್ಕಾಗಿ ಅಂದಾಜು ವೆಚ್ಚ, ಪವರ್ ಡ್ರಾ, ಶೇಖರಣಾ ಸಾಮರ್ಥ್ಯ ಮತ್ತು ನೆಟ್‌ವರ್ಕ್ ಅಂಕಿಅಂಶಗಳನ್ನು ವೀಕ್ಷಿಸಲು ಅನುಮತಿಸುತ್ತದೆ. ಇದು ಯೋಜನೆ ಮತ್ತು ಅಂದಾಜು ಸಾಧನವಾಗಿದೆ. ಇದು ಯಾವುದೇ ನೈಜ ಹಾರ್ಡ್‌ವೇರ್ ಅನ್ನು ಮಾರಾಟ ಮಾಡುವುದಿಲ್ಲ, ಕಾನ್ಫಿಗರ್ ಮಾಡುವುದಿಲ್ಲ, ಮೇಲ್ವಿಚಾರಣೆ ಮಾಡುವುದಿಲ್ಲ ಅಥವಾ ನಿರ್ವಹಿಸುವುದಿಲ್ಲ.",
  "legal.disclaimerSummary": "ಈ ಅಪ್ಲಿಕೇಶನ್‌ನಲ್ಲಿನ ಅಂದಾಜುಗಳು ಏನು ಮಾಡುತ್ತವೆ ಮತ್ತು ಅರ್ಥವಲ್ಲ.",
