  "plan.safeNote": "ಯೋಜನೆಯು ತಾತ್ಕಾಲಿಕ ಪ್ರಸ್ತಾವಿತ ಲ್ಯಾಬ್ ಪ್ರತಿಯನ್ನು ರಚಿಸುತ್ತದೆ. ನೀವು 'ನನ್ನ ಲ್ಯಾಬ್‌ಗೆ ಅನ್ವಯಿಸು' ಆಯ್ಕೆ ಮಾಡದ ಹೊರತು ನನ್ನ ಲ್ಯಾಬ್‌ನಲ್ಲಿ ಏನೂ ಬದಲಾಗುವುದಿಲ್ಲ.",
