  "plan.hint.remove": "ಪ್ರಸ್ತಾವನೆಯಲ್ಲಿ ಸಾಧನವನ್ನು ಆಯ್ಕೆಮಾಡಿ ಮತ್ತು ಅಳಿಸಿ. ಅದರ ಸಂಪರ್ಕಗಳನ್ನು ಪ್ರಸ್ತಾವನೆಯಲ್ಲಿ ಮಾತ್ರ ತೆಗೆದುಹಾಕಲಾಗುತ್ತದೆ.",
  "plan.hint.replace": "ಬದಲಿ ಸಾಧನವನ್ನು ಸೇರಿಸಿ, ಅದರ ಸಂಪರ್ಕಗಳನ್ನು ಸರಿಸಿ, ನಂತರ ಹಳೆಯ ಸಾಧನವನ್ನು ತೆಗೆದುಹಾಕಿ — ಅಥವಾ ಸಾಧನದ ವಿಶೇಷಣಗಳನ್ನು ಸಂಪಾದಿಸಿ.",
  "plan.hint.upgrade": "ಒಂದು ಸಾಧನವನ್ನು ಆಯ್ಕೆಮಾಡಿ ಮತ್ತು ಅದರ ವಿಶೇಷಣಗಳನ್ನು (ಸಂಗ್ರಹಣೆ, ನೆಟ್‌ವರ್ಕ್ ವೇಗ, CPU, RAM, ಶಕ್ತಿ) ಸಂಪಾದಿಸಿ.",
  "plan.hint.connection": "ಸಾಧನಗಳನ್ನು ಸಂಪರ್ಕಿಸಲು ಎರಡು ಸಂಪರ್ಕ ನೋಡ್‌ಗಳನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿ, ಅಥವಾ ಅದನ್ನು ತೆಗೆದುಹಾಕಲು ಸಂಪರ್ಕವನ್ನು ಆಯ್ಕೆಮಾಡಿ.",
  "plan.hint.storage": "ಡ್ರೈವ್‌ಗಳು ಮತ್ತು ಸಂಗ್ರಹಣಾ ಸಾಧನಗಳನ್ನು ಸೇರಿಸಿ, ತೆಗೆದುಹಾಕಿ ಅಥವಾ ಸಂಪಾದಿಸಿ. ಕೇವಲ ಕಚ್ಚಾ ಸಾಮರ್ಥ್ಯ.",
  "plan.hint.network": "ಸ್ವಿಚ್ ಸೇರಿಸಿ ಅಥವಾ ಬದಲಾಯಿಸಿ, ಸಂಪರ್ಕಗಳನ್ನು ಸರಿಸಿ, ಅಥವಾ ಮಾಡೆಲ್ ಮಾಡಿದ ಲಿಂಕ್ ವೇಗಗಳನ್ನು ಬದಲಾಯಿಸಿ.",
  "mylab.planChange": "ಬದಲಾವಣೆ ಯೋಜಿಸಿ",
