  "proposal.applyConfirmTitle": "ಈ ಪ್ರಸ್ತಾವಿತ ಬದಲಾವಣೆಯನ್ನು ನನ್ನ ಲ್ಯಾಬ್‌ಗೆ ಅನ್ವಯಿಸುವುದೇ?",
  "proposal.applyConfirmBody": "ಇದು ನಿಮ್ಮ ಪ್ರಸ್ತುತ ನನ್ನ ಲ್ಯಾಬ್ ಬೇಸ್‌ಲೈನ್ ಅನ್ನು ಪ್ರಸ್ತಾವಿತ ಕಾನ್ಫಿಗರೇಶನ್‌ನೊಂದಿಗೆ ಬದಲಾಯಿಸುತ್ತದೆ ಮತ್ತು ಬದಲಾವಣೆಯನ್ನು ಲ್ಯಾಬ್ ಇತಿಹಾಸದಲ್ಲಿ ದಾಖಲಿಸುತ್ತದೆ.",
  "proposal.discardConfirmTitle": "ಈ ಪ್ರಸ್ತಾವನೆಯನ್ನು ರದ್ದುಗೊಳಿಸುವುದೇ?",
  "proposal.discardConfirmBody": "ನಿಮ್ಮ ಪ್ರಸ್ತಾವಿತ ಬದಲಾವಣೆಗಳನ್ನು ಅಳಿಸಲಾಗುತ್ತದೆ. ನನ್ನ ಲ್ಯಾಬ್ ನಿಖರವಾಗಿ ಹಾಗೆಯೇ ಉಳಿಯುತ್ತದೆ.",
